    for i in range(n):
        for j in range(i + 1, n):
            if heights[i] < heights[j]:
                left[i].append(j)
            elif heights[i] > heights[j]:
                right[i].append(j)
    result = 0
    visited = [False for _ in range(n)]
    def dfs(i, path):
        nonlocal result
        if len(path) == n // 2:
            result = max(result, len(path))
