        for j in left[i]:
            if not visited[j]:
                visited[j] = True
                dfs(j, path + [j])
                visited[j] = False
        for j in right[i]:
            if not visited[j]:
                visited[j] = True
                dfs(j, path + [j])
                visited[j] = False
    dfs(0, [0])
    return n - result

